function upcomingPolls(){const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const items=(dataset.agenda||[]).filter(p=>p.date>=today&&!polls.some(q=>q.registration===p.registration)).sort((a,b)=>a.date.localeCompare(b.date));const formatDay=s=>new Date(s+'T12:00:00Z').toLocaleDateString('pt-BR',{day:'2-digit',month:'short',timeZone:'UTC'}).replace('.','');return '<section class="card" id="agenda-pesquisas" aria-labelledby="agenda-title"><div class="card-head"><div><div class="eyebrow">CALENDÁRIO ELEITORAL</div><h2 id="agenda-title">Próximas pesquisas</h2><p class="small">Datas previstas nos registros; horários de divulgação ainda não confirmados.</p></div><span class="badge">Horário de Brasília</span></div>'+(items.length?'<div class="agenda-list">'+items.slice(0,5).map(p=>'<div class="agenda-item" style="display:flex;align-items:center;gap:16px;padding:13px 0;border-bottom:1px solid var(--line)"><div style="min-width:68px;font-weight:800;font-size:18px">'+formatDay(p.date)+'</div><div style="flex:1"><strong>'+p.name+'</strong><div class="small">Registro '+p.registration+' · Coleta '+p.field+'</div></div><div style="text-align:right"><span class="small">Horário a confirmar</span><div><a class="link" target="_blank" rel="noopener noreferrer" href="'+p.source+'">Fonte ↗</a></div></div></div>').join('')+'</div>':'<p class="notice">Nenhuma pesquisa futura confirmada na agenda cadastrada.</p>')+'<p class="small" style="margin-top:16px">O registro no TSE informa a previsão, mas não garante publicação. Horários só serão exibidos quando confirmados. <a class="link" href="https://pesqele-divulgacao.tse.jus.br/" target="_blank" rel="noopener noreferrer">Consultar PesqEle ↗</a></p></section>';}
let polls=[], dataset=null;

const fmt=n=>n.toLocaleString('pt-BR',{maximumFractionDigits:2});const date=d=>d.slice(8,10)+'/'+d.slice(5,7);const main=document.querySelector('main');
const intro=(title,desc)=>`<div class="intro"><div><div class="eyebrow">OBSERVATÓRIO ELEITORAL / SEGUNDO TURNO</div><h1>${title}</h1><p class="sub">${desc}</p></div><span class="badge">Base de ${date(dataset.referenceDate)}/2026</span></div>`;
function comparableAverageHistory(){
 // Preserve legacy records in data.json, but never join incompatible models.
 // Only calculate a date when every institute has a documented, already-published
 // round with a known fieldwork end date. Missing historical metadata is a gap.
 const model=dataset.standardModel;
 const names=model.institutes.map(i=>i.name);
 const day=s=>Date.parse(s+'T00:00:00Z')/86400000;
 const cutoff=dataset.dataCutoffDate||dataset.referenceDate;
 const dates=[...new Set([...(dataset.history||[]).map(h=>h.date),cutoff])].sort();
 return dates.map(date=>{
  const rounds=names.map(name=>{
   const current=polls.find(p=>p.name===name);
   const past=(dataset.instituteHistory?.[name]||[]).filter(h=>h.date!==current?.date);
   const all=[...past,current].filter(Boolean);
   return all.filter(p=>p.date<=date&&p.fieldEnd&&p.fieldEnd<=date&&Number.isFinite(p.f)&&Number.isFinite(p.l)&&p.url).sort((a,b)=>b.date.localeCompare(a.date))[0];
  });
  if(rounds.some(p=>!p))return {date,available:rounds.filter(Boolean).length,total:names.length};
  const raw=rounds.map(p=>Math.pow(2,-Math.max(0,day(date)-day(p.fieldEnd))/(model.halfLifeDays||7)));
  const total=raw.reduce((a,b)=>a+b,0);
  const f=rounds.reduce((a,p,i)=>a+p.f*raw[i]/total,0);
  return {date,f,l:100-f,available:names.length,total:names.length};
 });
}
function chart(){
 const comparable=comparableAverageHistory();
 const valid=comparable.filter(p=>Number.isFinite(p.f));
 if(valid.length<2)return '<p class="notice">Histórico comparável ainda insuficiente. Há '+valid.length+' data(s) calculável(is) com os 14 institutos e a mesma regra de recência de 7 dias. Não ligamos médias de metodologias diferentes nem estimamos valores ausentes.</p>'+(valid.length?'<p class="small">Data comparável disponível: '+valid.map(p=>date(p.date)+': Flávio '+fmt(p.f)+'%, Lula '+fmt(p.l)+'%').join('; ')+'</p>':'');
 return timeChart(valid);
}
function sensitivityChart(latest){
  const range=3, low=44, high=56;
  const values=[latest.f,latest.l];
  const minimum=Math.min(...values)-range,maximum=Math.max(...values)+range;
  // A shared independent percentage scale. Expand automatically if future data require it.
  const axisMin=Math.min(low,Math.floor(minimum)),axisMax=Math.max(high,Math.ceil(maximum));
  const x=n=>((n-axisMin)/(axisMax-axisMin)*100).toFixed(4)+'%';
  const ticks=[];for(let n=axisMin;n<=axisMax;n+=2)ticks.push(n);
  const row=(name,value,color)=>{
    const left=value-range,right=value+range;
    return `<div class="interval-row"><div class="interval-name">${name}</div><div class="interval-plot" role="img" aria-label="${name}: ${fmt(value)} por cento, faixa hipotética de ${fmt(left)} a ${fmt(right)} por cento"><span class="interval-line ${color}" style="left:${x(left)};width:${(6/(axisMax-axisMin)*100).toFixed(4)}%"><i class="interval-cap first"></i><i class="interval-cap last"></i></span><span class="interval-marker ${color}" style="left:${x(value)}"></span><span class="interval-value" style="left:${x(value)}">${fmt(value)}%</span><span class="interval-limit left" style="left:${x(left)}">${fmt(left)}%</span><span class="interval-limit right" style="left:${x(right)}">${fmt(right)}%</span></div></div>`;
  };
  return `<section class="sensitivity interval-chart" aria-labelledby="interval-title"><h3 id="interval-title">Intervalos ilustrativos</h3><div class="interval-layout"><div class="interval-grid" aria-hidden="true">${ticks.map(n=>`<span class="interval-gridline ${n===50?'central':''}" style="left:${x(n)}"></span>`).join('')}</div>${row('Flávio Bolsonaro',latest.f,'violet')}${row('Lula',latest.l,'coral')}<div class="interval-axis"><span class="interval-axis-spacer"></span><div class="interval-ticks">${ticks.map(n=>`<span style="left:${x(n)}">${n}%</span>`).join('')}</div></div></div><p class="sensitivity-caption"><strong>EXEMPLO VISUAL · FAIXA HIPOTÉTICA DE ±3 P.P.</strong><span>Não representa margem de erro nem intervalo de confiança da média ponderada.</span></p></section>`;
}
function recencyAggregate(){
 const model=dataset.standardModel;if(!model||!model.enabled)return null;
 const cutoff=dataset.dataCutoffDate||dataset.referenceDate;
 const day=s=>Date.parse(s+'T00:00:00Z')/86400000;
 const halfLife=model.halfLifeDays||7;
 const rows=model.institutes.map(i=>{
  const p=polls.filter(q=>q.name===i.name&&q.date<=cutoff&&q.fieldEnd&&q.fieldEnd<=cutoff&&Number.isFinite(q.f)&&Number.isFinite(q.l)).sort((a,b)=>b.fieldEnd.localeCompare(a.fieldEnd))[0];
  if(!p)return null;
  const ageDays=Math.max(0,day(cutoff)-day(p.fieldEnd));
  return {name:i.name,f:p.f,l:p.l,fieldEnd:p.fieldEnd,ageDays,base:100/model.institutes.length,raw:Math.pow(2,-ageDays/halfLife)};
 }).filter(Boolean);
 if(!rows.length||rows.length!==model.institutes.length)return null;
 const total=rows.reduce((sum,r)=>sum+r.raw,0);
 rows.forEach(r=>r.effective=100*r.raw/total);
 const f=rows.reduce((sum,r)=>sum+r.f*r.effective/100,0);
 const sd=Math.sqrt(rows.reduce((sum,r)=>sum+r.effective/100*(r.f-f)**2,0));
 rows.forEach(r=>r.z=sd?(r.f-f)/sd:0);
 return {f,l:100-f,sd,rows,excluded:polls.filter(p=>!rows.some(r=>r.name===p.name)).map(p=>p.name)};
}
function average(){const rec=recencyAggregate();const cutoff=dataset.dataCutoffDate||dataset.referenceDate;const latest=rec?{...dataset.history.at(-1),f:rec.f,l:rec.l,date:cutoff}:dataset.history.at(-1);main.innerHTML=intro('O cenário, em perspectiva.','Pesquisas reunidas, critérios transparentes e uma leitura contextualizada da disputa presidencial.')+`<section class="hero" aria-labelledby="average-title"><div class="hero-top"><span id="average-title">SE A ELEIÇÃO FOSSE HOJE · MÉDIA PONDERADA</span><span class="tag">Modelo padrão</span></div><div class="scores"><div class="candidate"><span class="violet">●</span> Flávio Bolsonaro<div class="score">${fmt(latest.f)}<small>%</small></div></div><div class="difference">Diferença<strong>${fmt(latest.f-latest.l)}</strong>pontos percentuais</div><div class="candidate">Lula <span class="red">■</span><div class="score">${fmt(latest.l)}<small>%</small></div></div></div><div class="split" style="--share:${latest.f}%" aria-hidden="true"><span></span><span></span></div>${sensitivityChart(latest)}<div class="hero-bottom"><span>Votos válidos · ${rec?rec.rows.length:dataset.standardModel.institutes.length} institutos no modelo · modelo padrão · recência de 7 dias</span><span>Pesquisas até ${date(cutoff)}/2026</span></div></section><p class="notice">${rec?'Média de 14 institutos com peso-base igual e meia-vida de 7 dias desde o fim da coleta. '+(rec.excluded.length?rec.excluded.length+' levantamentos sem dados válidos ficaram fora do cálculo. ':''):'Média consolidada preservada: faltam dados individuais de institutos configurados, portanto nenhum recálculo parcial foi aplicado.'} Data de corte: ${date(cutoff)}/2026. Só pesquisas efetivamente divulgadas entram no cálculo; sem novas publicações, a média e a data de corte permanecem inalteradas. Sem margem de erro agregada validada; não é uma previsão eleitoral. <a href="#metodologia">Entenda o método</a>.</p>${trendSection()}<div class="grid"><section class="card"><div class="card-head"><div><h2>Evolução da média</h2><p class="small">${comparableAverageHistory().filter(p=>Number.isFinite(p.f)).length} registros comparáveis · até ${date(latest.date)}</p></div><span class="badge">Histórico</span></div><div class="legend"><span><i class="dot"></i>Flávio</span><span><i class="dot r"></i>Lula · linha tracejada</span></div>${chart()}<p class="small">Atualizações de Datafolha, PoderData/Aya e Gerp substituem as rodadas anteriores. Os registros anteriores permanecem arquivados, mas não são ligados à média atual porque faltam dados de coleta para reconstruí-los com a mesma metodologia. Novos pontos serão exibidos somente quando houver rodadas documentadas e comparáveis. Sem projeção ou intervalo de confiança estimado.</p><details><summary>Consultar datas e disponibilidade</summary><table><tr><th>Data</th><th>Flávio</th><th>Lula</th><th>Institutos documentados</th></tr>${comparableAverageHistory().map(p=>`<tr><td>${date(p.date)}</td><td>${Number.isFinite(p.f)?fmt(p.f)+'%':'Não comparável'}</td><td>${Number.isFinite(p.l)?fmt(p.l)+'%':'Não comparável'}</td><td>${p.available} de ${p.total}</td></tr>`).join('')}</table></details></section><section class="card"><h2>Pesos dos institutos</h2><p class="small">Comparação entre pesos iguais (referência) e pesos efetivos por recência, com meia-vida de 7 dias.</p><div class="weight-legend"><span><i class="weight-key old"></i>Igual</span><span><i class="weight-key new"></i>Recência (7 dias)</span></div>${(rec?rec.rows.map(r=>({name:r.name,previous:r.base,current:r.effective})):dataset.standardModel.institutes.map(i=>({name:i.name,previous:100/dataset.standardModel.institutes.length,current:i.weightPercent}))).map(w=>`<div class="weight-comparison"><div class="weight-row"><span>${w.name}</span><strong>${fmt(w.current)}%</strong></div><div class="weight-pair"><i style="width:${Math.min(100,w.previous/20*100)}%" title="Peso igual: ${fmt(w.previous)}%"></i><b style="width:${Math.min(100,w.current/20*100)}%" title="Por recência: ${fmt(w.current)}%"></b></div></div>`).join('')}<p class="small">Escala de 0 a 20%. Pesos calculados pelo encerramento da coleta; sem classificação subjetiva dos institutos.</p><a class="link" href="#metodologia">Conheça os critérios ↗</a></section></div><div class="section-title"><h2>Por trás dos números</h2><a class="link" href="#pesquisas">Explorar pesquisas ↗</a></div><div class="mini-grid"><div class="mini"><strong>${polls.length}</strong><span class="small">Levantamentos com fonte nesta versão</span></div><div class="mini"><strong>${dataset.history.length}</strong><span class="small">Registros históricos da média</span></div><div class="mini"><strong>100% visível</strong><span class="small">Critérios, fontes e limitações</span></div></div>`;}
function research(){main.innerHTML=intro('Cada pesquisa, em detalhe.','Compare os levantamentos publicados e consulte suas fontes. Os resultados abaixo estão em votos válidos.')+`<div class="tools"><label class="field">Buscar instituto<input id="search" type="search" placeholder="Nome do instituto" autocomplete="off"></label><label class="field">Divulgação a partir de<input id="from" type="date" min="2026-10-01" max="${dataset.referenceDate}"></label><label class="field">Ordenar<select id="sort"><option value="new">Mais recentes</option><option value="old">Mais antigas</option><option value="name">Nome do instituto</option></select></label><button class="button" id="export">Exportar CSV</button></div><p class="small" id="count" aria-live="polite"></p><div class="table-wrap"><table><caption class="sr-only">Pesquisas eleitorais em votos válidos</caption><thead><tr><th>Instituto / data de divulgação</th><th>Flávio</th><th>Lula</th><th>Coleta</th><th>Amostra</th><th>Margem publicada</th><th>Fonte</th></tr></thead><tbody id="rows"></tbody></table><div id="empty" class="empty" hidden>Nenhuma pesquisa encontrada. Ajuste a busca ou a data.</div></div><div id="mobile-poll-cards" class="mobile-poll-cards" aria-label="Pesquisas publicadas"></div>${upcomingPolls()}<p class="notice">Quaest e Palver foram convertidas de votos totais para válidos. Para Flávio: Quaest, 46 ÷ (46 + 44) = 51,11%; Palver, 50 ÷ (50 + 49) = 50,51%. A conversão utiliza os percentuais arredondados publicados. As margens são as publicadas nos levantamentos, sem recálculo para a conversão.</p><section class="card"><h2>Uma base em construção</h2><p class="sub">Esta página reúne ${polls.length} levantamentos com fontes identificadas. A média atual usa uma pesquisa por instituto, pesos-base iguais e redução exponencial por recência (meia-vida de 7 dias, contada do fim da coleta). Os resultados originais permanecem visíveis nesta tabela.</p><details><summary>Como os dados são atualizados?</summary><p>Esta primeira versão utiliza uma base editorial com fontes identificadas. A cada boletim atualizado nesta conversa, os dados revisados podem ser publicados no site. Enquanto a página está aberta, ela verifica novas versões a cada 30 segundos e ao voltar à aba. A verificação não pesquisa novos levantamentos: ela recebe os boletins publicados.</p></details></section>`;['search','from','sort'].forEach(id=>document.getElementById(id).addEventListener('input',rows));document.getElementById('export').addEventListener('click',download);rows();}
function filtered(){let p=polls.filter(p=>p.name.toLowerCase().includes(document.getElementById('search').value.toLowerCase())&&(!document.getElementById('from').value||p.date>=document.getElementById('from').value));let s=document.getElementById('sort').value;return p.sort((a,b)=>s==='name'?a.name.localeCompare(b.name):s==='old'?a.date.localeCompare(b.date):b.date.localeCompare(a.date));}
function rows(){const p=filtered();document.getElementById('count').textContent=`${p.length} de ${polls.length} levantamentos · Referência: ${date(dataset.referenceDate)}/2026`;document.getElementById('empty').hidden=p.length>0;document.getElementById('rows').innerHTML=p.map(p=>`<tr><td><strong>${p.name}</strong><br><span class="small">${date(p.date)}/2026${p.converted?' · convertido':''}</span></td><td class="num fv">${fmt(p.f)}%</td><td class="num lv">${fmt(p.l)}%</td><td>${p.field}</td><td>${p.n?fmt(p.n):'Não recuperada'}</td><td>${p.margin}</td><td><a class="link" target="_blank" rel="noopener noreferrer" href="${p.primaryUrl||p.url}" aria-label="Fonte de ${p.name}, abre em nova aba">${p.primaryUrl?"Instituto":"Divulgação"} ↗</a><br><a class="link" target="_blank" rel="noopener noreferrer" href="${p.url}">${p.primaryUrl?"Notícia ↗":"Detalhes ↗"}</a>${p.registration?`<br><a class="link" target="_blank" rel="noopener noreferrer" href="https://pesqele-divulgacao.tse.jus.br/" title="Número informado na divulgação; conferência individual pendente">TSE: ${p.registration} ↗</a>`:""}</td></tr>`).join('');document.getElementById('mobile-poll-cards').innerHTML=p.map(q=>`<article class="mobile-poll-card"><div class="mobile-poll-head"><div><strong>${q.name}</strong><div class="small">Divulgação: ${date(q.date)}/2026${q.converted?' · válidos convertidos':''}</div></div></div><div class="mobile-poll-scores"><div><span>Flávio</span><strong class="fv">${fmt(q.f)}%</strong></div><div><span>Lula</span><strong class="lv">${fmt(q.l)}%</strong></div></div><details><summary>Ver detalhes</summary><dl><div><dt>Coleta</dt><dd>${q.field}</dd></div><div><dt>Amostra</dt><dd>${q.n?fmt(q.n):'Não recuperada'}</dd></div><div><dt>Margem publicada</dt><dd>${q.margin}</dd></div>${q.registration?`<div><dt>Registro TSE</dt><dd>${q.registration}</dd></div>`:''}</dl><div class="mobile-poll-links"><a href="${q.primaryUrl||q.url}" target="_blank" rel="noopener noreferrer">Fonte principal ↗</a>${q.primaryUrl?`<a href="${q.url}" target="_blank" rel="noopener noreferrer">Notícia ↗</a>`:''}</div></details></article>`).join('');}
function download(){const csv='\uFEFF'+[['Instituto','Divulgação','Flávio válidos (%)','Lula válidos (%)','Coleta','Amostra','Margem publicada','Fonte'],...filtered().map(p=>[p.name,p.date,fmt(p.f),fmt(p.l),p.field,p.n||'',p.margin,p.url])].map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(';')).join('\r\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='pulsa-pesquisas-'+dataset.referenceDate+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function methodology(){
 const rec=recencyAggregate();
 main.innerHTML=intro('Transparência faz parte do método.','Peso-base igual por instituto e recência da coleta com meia-vida fixa de sete dias.')+`<section class="card"><h2>Critérios e fórmula</h2><p>Uma pesquisa nacional mais recente por instituto, divulgada até a data de corte, com votos válidos e encerramento de coleta informado. Atualmente, 14 institutos participam da média. Não atribuímos pesos pela reputação, por preferência eleitoral ou por erros históricos do primeiro turno.</p><p><strong>Data de referência:</strong> ${date(dataset.dataCutoffDate||dataset.referenceDate)}/2026. A idade da pesquisa é contada em dias desde o encerramento da coleta, e não desde a divulgação.</p><p><strong>Meia-vida:</strong> sete dias. Uma pesquisa encerrada há sete dias tem metade do peso bruto de uma encerrada hoje; todas as participações são normalizadas para somar 100%.</p><div class="formula">Idadeᵢ = dias entre o fim da coletaᵢ e a data de referência</div><div class="formula">Peso brutoᵢ = 2 ^ (−idadeᵢ ÷ 7)</div><div class="formula">Pesoᵢ = peso brutoᵢ ÷ Σ pesos brutos</div><div class="formula">Média = Σ (pesoᵢ × votos válidosᵢ)</div><p>Sem novas pesquisas, o envelhecimento uniforme não altera os pesos relativos nem a média. Ao substituir ou acrescentar um levantamento, os pesos são recalculados pela mesma regra. A meia-vida de sete dias é uma escolha editorial fixa, não um parâmetro estatisticamente validado por testes retrospectivos.</p><h2>O que pode ser inferido</h2><p>A média resume pesquisas de institutos diferentes, sem produzir probabilidade de vitória ou margem de erro agregada validada. Diferenças pequenas não comprovam liderança estatisticamente significativa.</p><h2>Dispersão e sensibilidade</h2><p>Desvio padrão ponderado entre institutos: <strong>${rec?fmt(rec.sd):'indisponível'} p.p.</strong> Não é margem de erro nem intervalo de confiança. Faixas de ±3 p.p. são ilustrativas.</p><h2>Histórico e tendências</h2><p>Os registros históricos anteriores foram preservados, mas pertencem a um modelo antigo e não são ligados à média atual. Só exibimos evolução comparável quando há rodadas com fim de coleta e fonte documentados para todos os institutos. A aba Tendências aplica os mesmos pesos de recência às pesquisas e mantém separada a extrapolação condicional até 25/10, que não constitui previsão eleitoral.</p><h2>Fontes</h2><p>As fontes e os registros informados de cada levantamento estão na aba Pesquisas. A consulta individual de registros no PesqEle continua pendente onde indicado; o registro não representa certificação do resultado pelo TSE.</p></section>`;
}

function trendModel(){
 const day=s=>Date.parse(s+'T00:00:00Z')/86400000;
 const cutoff=dataset.dataCutoffDate||dataset.referenceDate;
 const current=recencyAggregate();
 const weights=new Map((current?.rows||[]).map(r=>[r.name,r.effective]));
 // One latest documented round per institute. Keep all observations on or before the cutoff.
 const input=polls.filter(p=>weights.has(p.name)&&p.url&&p.registration&&p.fieldEnd&&Number.isFinite(p.f)&&p.date<=cutoff&&p.fieldEnd<=cutoff)
  .map(p=>({t:day(p.fieldEnd),f:p.f,w:weights.get(p.name)}));
 if(input.length<4)return null;
 const start=Math.min(...input.map(p=>p.t)),end=Math.max(...input.map(p=>p.t));
 if(end-start<2)return null;
 const points=[],bandwidth=3.5,ridge=18;
 for(let t=start;t<=end;t++){
  let sw=0,sx=0,sxx=0,sy=0,sxy=0;
  for(const p of input){const x=p.t-t,w=p.w*Math.exp(-.5*(x/bandwidth)**2);sw+=w;sx+=w*x;sxx+=w*x*x;sy+=w*p.f;sxy+=w*x*p.f;}
  const denom=sw*(sxx+ridge)-sx*sx;
  const f=Math.max(0,Math.min(100,denom>0?(sy*(sxx+ridge)-sx*sxy)/denom:sy/sw));
  points.push({date:new Date(t*86400000).toISOString().slice(0,10),f,l:100-f});
 }
 // Preserve the fitted series before anchoring the last displayed estimate.
 const fittedPoints=points.map(p=>({...p}));
 // Anchor the most recent estimate to the same documented weighted mean as the main panel.
 if(current)points[points.length-1]={...points[points.length-1],f:current.f,l:current.l};
 return {points,fittedPoints,n:input.length,cutoff,displayDate:new Date(end*86400000).toISOString().slice(0,10),lastPollDate:new Date(end*86400000).toISOString().slice(0,10)};
}

function conditionalProjection(model){
 const observed=model.points,last=observed.at(-1),lastTime=Date.parse(last.date+'T00:00:00Z');
 const election='2026-10-25',days=Math.max(0,Math.round((Date.parse(election+'T00:00:00Z')-lastTime)/86400000));
 // Estimate the recent slope from unanchored fitted values; the last point
 // is anchored to the main aggregate and must not create a fictitious swing.
 const trend=Array.isArray(model.fittedPoints)?model.fittedPoints:observed;
 const recent=trend.slice(-6);
 const t0=Date.parse(recent[0].date+'T00:00:00Z')/86400000;
 const xs=recent.map(p=>Date.parse(p.date+'T00:00:00Z')/86400000-t0);
 const xm=xs.reduce((a,b)=>a+b,0)/xs.length;
 const ym=recent.reduce((a,p)=>a+p.f,0)/recent.length;
 const covariance=recent.reduce((a,p,i)=>a+(xs[i]-xm)*(p.f-ym),0);
 const variance=xs.reduce((a,x)=>a+(x-xm)**2,0);
 const rawSlope=variance>0?covariance/variance:0;
 const slope=Math.max(-.15,Math.min(.15,rawSlope));
 const f=Math.max(0,Math.min(100,last.f+slope*days));
 return {date:election,days,slope,rawSlope,f,l:100-f,from:last};
}

function projectionChart(points,projection){
 const start=Date.parse(points[0].date),finish=Date.parse(projection.date),x=p=>65+(Date.parse(p.date)-start)/(finish-start||1)*815;
 const vals=[...points.flatMap(p=>[p.f,p.l]),projection.f,projection.l];
 const low=Math.floor(Math.min(43,...vals)-1),high=Math.ceil(Math.max(57,...vals)+1),y=v=>25+(high-v)/(high-low)*265;
 const last=projection.from,xf=x(projection),xl=x(last);
 let out=`<svg class="projection-svg" viewBox="0 0 970 350" role="img" aria-label="Curvas suavizadas até ${date(last.date)} e extrapolação condicional tracejada até 25 de outubro: Flávio ${fmt(projection.f)}%, Lula ${fmt(projection.l)}%. Não é previsão eleitoral.">`;
 for(let i=0;i<=4;i++){const v=low+(high-low)*i/4;out+=`<path d="M65 ${y(v)}H880" stroke="#e3e0e5" stroke-dasharray="3 6"/><text x="10" y="${y(v)+5}" font-size="15" fill="#68636c">${fmt(v)}%</text>`;}
 out+=`<path d="M${xl} 25V290" stroke="#aaa" stroke-dasharray="3 5"/>`;
 for(const [key,color] of [['f','#7774df'],['l','#f44330']]){
   out+=`<polyline fill="none" stroke="${color}" stroke-width="3" points="${points.map(p=>x(p)+','+y(p[key])).join(' ')}"/>`;
   out+=`<path d="M${xl} ${y(last[key])}L${xf} ${y(projection[key])}" stroke="${color}" stroke-width="3" stroke-dasharray="9 7" fill="none"/>`;
   out+=`<circle cx="${xf}" cy="${y(projection[key])}" r="5" fill="${color}"/><text x="890" y="${y(projection[key])+5}" fill="${color}" font-size="17" font-weight="700">${fmt(projection[key])}%</text>`;
 }
 out+=`<text x="65" y="326" fill="#68636c" font-size="15">${date(points[0].date)}</text><text x="${xl}" y="326" text-anchor="middle" fill="#68636c" font-size="15">${date(last.date)}</text><text x="${xf}" y="326" text-anchor="middle" fill="#68636c" font-size="15">25/10</text></svg>`;
 return out;
}

function openVoteSection(){
 const raw=Array.isArray(dataset.openVote)?dataset.openVote:[];
 const rows=raw.filter(p=>p.scope==='second_round'&&p.basis==='total_respondents'&&p.categoriesExclusive===true&&typeof p.institute==='string'&&/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(p.date)&&Number.isFinite(p.blankNull)&&Number.isFinite(p.undecided)&&p.blankNull>=0&&p.undecided>=0&&p.blankNull+p.undecided<=100&&typeof p.source==='string'&&p.source.startsWith('https://'));
 const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const groups=rows.reduce((a,p)=>((a[p.institute]??=[]).push(p),a),{});
 const latest=[...new Map([...rows].sort((a,b)=>a.date.localeCompare(b.date)).map(p=>[p.institute,p])).values()];
 const mean=k=>latest.reduce((sum,p)=>sum+p[k],0)/latest.length;
 const overview=latest.length?(()=>{
   const blank=mean('blankNull'),undecided=mean('undecided'),total=blank+undecided;
   const display=v=>v.toLocaleString('pt-BR',{minimumFractionDigits:1,maximumFractionDigits:1});
   const count=latest.length;
   const title=count===1?'Última pesquisa · '+safe(latest[0].institute):'Média simples · '+count+' institutos';
   const metric=(label,value,kind)=>'<div class="open-vote-metric '+kind+'"><span>'+label+'</span><strong>'+display(value)+'%</strong></div>';
   return '<div class="open-vote-overview" aria-label="'+safe(title)+'"><div class="eyebrow">PANORAMA GERAL</div><p class="open-vote-overview-subtitle">'+title+'</p><div class="open-vote-metrics">'+metric('Brancos/nulos',blank,'blank')+metric('Indecisos',undecided,'undecided')+metric('Total',total,'total')+'</div><div class="open-vote-overview-track" role="img" aria-label="Brancos e nulos: '+display(blank)+'%; indecisos: '+display(undecided)+'%; demais respostas: '+display(100-total)+'%"><span class="blank" style="width:'+blank+'%"></span><span class="undecided" style="width:'+undecided+'%"></span></div><p class="open-vote-overview-summary"><strong>'+display(total)+'%</strong> não indicaram voto em um dos finalistas.</p><p class="small">'+(count>1?'Última rodada de cada instituto, com pesos iguais. Média descritiva, sem margem de erro própria.':'Resultado de um instituto; não é média entre institutos.')+' Brancos/nulos e indecisos não representam necessariamente votos disponíveis para os candidatos.</p></div>';
 })():'';

 const series=Object.entries(groups).sort(([a],[b])=>a.localeCompare(b)).map(([name,points])=>{
   const ordered=points.sort((a,b)=>a.date.localeCompare(b.date));
   const latest=ordered.at(-1);
   const latestText='<p class="small"><strong>Última rodada:</strong> '+date(latest.date)+' · Brancos/nulos: '+fmt(latest.blankNull)+'% · Indecisos: '+fmt(latest.undecided)+'% · Total: '+fmt(latest.blankNull+latest.undecided)+'%</p>';
   const table='<div class="table-wrap"><table><thead><tr><th>Data</th><th>Brancos/nulos</th><th>Indecisos</th><th>Total</th><th>Fonte</th></tr></thead><tbody>'+ordered.map(p=>'<tr><td>'+date(p.date)+'</td><td>'+fmt(p.blankNull)+'%</td><td>'+fmt(p.undecided)+'%</td><td>'+fmt(p.blankNull+p.undecided)+'%</td><td><a href="'+safe(p.source)+'" target="_blank" rel="noopener noreferrer">Fonte ↗</a></td></tr>').join('')+'</tbody></table></div>';
   const graph=ordered.length<2?'<p class="small">Ainda há apenas uma rodada comparável deste instituto.</p>':(()=>{
     const first=ordered[0],last=ordered.at(-1);
     const pct=v=>v.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%';
     const delta=v=>(v>0?'+':'')+v.toLocaleString('pt-BR',{maximumFractionDigits:1})+' p.p.';
     const defs=[
       {label:'Brancos/nulos',key:p=>p.blankNull,color:'#7774df'},
       {label:'Indecisos',key:p=>p.undecided,color:'#e45440'},
       {label:'Total',key:p=>p.blankNull+p.undecided,color:'#303039'}
     ];
     const legend=defs.map(d=>{
       const before=d.key(first),after=d.key(last),change=Math.round((after-before)*10)/10;
       return '<div class="open-vote-series-card" style="--series-color:'+d.color+'"><span class="open-vote-series-label"><i aria-hidden="true"></i>'+d.label+'</span><div class="open-vote-series-numbers"><span>'+pct(before)+'</span><span aria-hidden="true">→</span><strong>'+pct(after)+'</strong><em>'+delta(change)+'</em></div></div>';
     }).join('');
     const w=600,h=280,left=48,right=568,top=20,bottom=228;
     const values=ordered.flatMap(p=>defs.map(d=>d.key(p)));
     const max=Math.max(10,Math.ceil(Math.max(...values)/2)*2);
     const x=i=>left+30+i*(right-left-60)/(ordered.length-1);
     const y=v=>bottom-(v/max)*(bottom-top);
     const grid=Array.from({length:6},(_,i)=>{const value=i*max/5,yy=y(value);return '<line x1="'+left+'" y1="'+yy+'" x2="'+right+'" y2="'+yy+'" stroke="#e8e5ed" stroke-width="1"/><text x="'+(left-8)+'" y="'+(yy+4)+'" text-anchor="end" fill="#77717e" font-size="12">'+value.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%</text>';}).join('');
     const lines=defs.map(d=>{
       const points=ordered.map((p,i)=>x(i)+','+y(d.key(p))).join(' ');
       return '<polyline points="'+points+'" fill="none" stroke="'+d.color+'" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/>'+ordered.map((p,i)=>'<circle cx="'+x(i)+'" cy="'+y(d.key(p))+'" r="5.5" fill="#fff" stroke="'+d.color+'" stroke-width="3"/>').join('');
     }).join('');
     const dates=ordered.map((p,i)=>'<text x="'+x(i)+'" y="'+(bottom+30)+'" text-anchor="middle" font-size="14" fill="#5c5664">'+date(p.date)+'</text>').join('');
     return '<div class="open-vote-evolution" aria-label="Evolução entre '+date(first.date)+' e '+date(last.date)+'"><div class="open-vote-evolution-head"><strong>Evolução das respostas</strong><span>'+date(first.date)+' → '+date(last.date)+'</span></div><div class="open-vote-series-legend" aria-label="Legenda e valores das séries">'+legend+'</div><svg class="open-vote-evolution-chart" viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Linhas de evolução de brancos e nulos, indecisos e total; valores exatos na legenda acima">'+grid+lines+dates+'</svg><p class="small">Os pontos são resultados de pesquisas, não estimativas diárias. A variação está em pontos percentuais; duas rodadas não comprovam tendência consolidada.</p></div>';
   })();
   return '<div class="open-vote-institute"><h3>'+safe(name)+'</h3>'+latestText+graph+table+'</div>';
 }).join('');
 return '<section class="card open-vote-section" aria-labelledby="open-vote-title"><div class="card-head"><div><div class="eyebrow">ELEITORES SEM VOTO EM UM DOS FINALISTAS</div><h2 id="open-vote-title">O voto ainda em aberto</h2><p class="sub">Evolução de brancos/nulos e indecisos nas pesquisas de segundo turno.</p></div></div><div class="open-vote-legend"><span><i class="open-vote-key key-blank"></i>Brancos e nulos</span><span><i class="open-vote-key key-undecided"></i>Indecisos</span><span><i class="open-vote-key key-total"></i>Total</span></div>'+overview+(rows.length?series:'<p class="notice">Aguardando rodadas verificadas com percentuais separados de brancos/nulos e indecisos sobre o total de entrevistados. Nenhum valor foi estimado ou convertido a partir de votos válidos.</p>')+'<p class="small">As séries são exibidas por instituto, sem misturar perguntas ou métodos distintos. O total soma brancos/nulos e indecisos apenas quando as categorias são mutuamente exclusivas na mesma pergunta. Não representa automaticamente votos que migrarão para algum candidato.</p></section>';
}
function experimentalTrend(){
 const model=trendModel();
 if(!model){main.innerHTML=intro('Tendência experimental.','Ainda não há observações suficientes para calcular uma trajetória.')+'<p class="notice">Sem dados suficientes para exibir a curva. O painel principal permanece disponível.</p>';return;}
 const ps=model.points,first=ps[0],last=ps.at(-1),change=last.f-first.f,projection=conditionalProjection(model);
 const direction=Math.abs(change)<.5?'Estabilidade aparente':change>0?'Alta aparente de Flávio':'Alta aparente de Lula';
 main.innerHTML=intro('Tendência experimental.','Uma leitura exploratória da direção das pesquisas, separada da média principal.')+
 `<section class="card trend-card experimental-trend-card"><div class="card-head"><div><div class="eyebrow">MODELO ESTATÍSTICO EXPERIMENTAL</div><h2>Se a eleição fosse hoje?</h2><p class="sub">Curva suavizada de pesquisas com fonte e registro informados até ${date(model.cutoff)}/2026, encerrada na última data de coleta, ${date(model.lastPollDate)}. Usa os pesos do modelo padrão e coincide com a média principal no ponto final.</p></div><span class="badge">${model.n} institutos</span></div>
 <div class="trend-summary"><div><span>Leitura do período</span><strong>${direction}</strong></div><div><span>Variação suavizada de Flávio</span><strong class="fv">${change>0?'+':''}${fmt(change)} p.p.</strong></div><div><span>Período da curva</span><strong>${date(first.date)} a ${date(last.date)}</strong></div></div>
 <div class="forecast-numbers trend-current-numbers" aria-label="Valores suavizados em ${date(last.date)}"><div><span>Flávio Bolsonaro</span><strong class="fv">${fmt(last.f)}%</strong></div><div><span>Lula</span><strong class="lv">${fmt(last.l)}%</strong></div></div>
 <p class="small">Estimativas suavizadas em ${date(last.date)}. Não são resultados de uma pesquisa realizada nesse dia.</p>
 <div class="legend"><span><i class="dot"></i>Flávio Bolsonaro</span><span><i class="dot r"></i>Lula · linha tracejada</span></div>
 ${timeChart(ps)}
 <section class="conditional-forecast" aria-labelledby="conditional-title"><div class="eyebrow">SIMULAÇÃO · NÃO É PREVISÃO ELEITORAL</div><h3 id="conditional-title">E se a tendência continuar até 25/10?</h3><p class="small">Continuação condicional até 25/10, com inclinação estimada na curva suavizada antes do ajuste do ponto final e limitada a 0,15 ponto percentual por dia. Não é previsão eleitoral.</p>
 <div class="forecast-numbers"><div><span>Flávio Bolsonaro</span><strong class="fv">${fmt(projection.f)}%</strong></div><div><span>Lula</span><strong class="lv">${fmt(projection.l)}%</strong></div></div>
 <div class="legend"><span><i class="dot"></i>Flávio</span><span><i class="dot r"></i>Lula</span><span>Linha tracejada: simulação</span></div>
 ${projectionChart(ps,projection)}
 <p class="notice">A simulação pressupõe continuidade da tendência recente e não incorpora eventos futuros, indecisos, abstenção nem mudanças de comportamento. Não possui intervalo de confiança validado. Não indica probabilidade de vitória.</p></section>
 <p class="small"><strong>Como ler:</strong> cada ponto é uma estimativa suavizada baseada nas pesquisas próximas daquela data, posicionadas pela data final da coleta. A curva termina na última coleta documentada; não cria pontos em dias posteriores sem pesquisa. O ponto final é ancorado na média ponderada principal. A simulação começa nesse ponto, mas sua inclinação é calculada sem o ajuste final para evitar um salto artificial. A regressão usa pesos institucionais e dá mais influência a levantamentos temporalmente próximos, restringindo oscilações bruscas. Não são novas pesquisas nem percentuais de intenção de voto observados diariamente.</p>
 ${openVoteSection()}
 <p class="notice"><strong>Limitações:</strong> curva descritiva com poucos levantamentos e sem correção validada de efeitos próprios de cada instituto. Não é rede neural, previsão de resultado ou tendência estatisticamente comprovada. Não há intervalo de confiança calibrado. A tendência utiliza os mesmos pesos por recência do modelo principal.</p>
 <details><summary>Dados da curva e parâmetros</summary><p class="small">Janela gaussiana: 3,5 dias; regularização da inclinação: 18; pesos do modelo padrão; uma pesquisa recente por instituto; ponto final ancorado na média principal. Parâmetros exploratórios, sem validação retrospectiva. A extrapolação condicional usa a inclinação dos últimos seis pontos suavizados, limitada a ±0,15 p.p. por dia até 25/10. Não foi calibrada em eleições anteriores.</p><div class="table-wrap"><table><tr><th>Data</th><th>Flávio suavizado</th><th>Lula suavizado</th></tr>${ps.map(p=>`<tr><td>${date(p.date)}</td><td>${fmt(p.f)}%</td><td>${fmt(p.l)}%</td></tr>`).join('')}</table></div></details></section>`;
}

function rejection(){
  const records=(Array.isArray(dataset.rejection)?dataset.rejection:[]).filter(p=>p.scope==='second_round');
  const groups=[
    {id:'declared',title:'Rejeição declarada',description:'Respostas sobre em quem o eleitor não votaria de jeito nenhum. A redação da pergunta e a possibilidade de múltiplas respostas devem ser conferidas em cada levantamento.'},
    {id:'exclusive',title:'Rejeição exclusiva',description:'Eleitores que rejeitam apenas um dos candidatos. Não é diretamente comparável à rejeição declarada.'}
  ];
  const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const render=p=>'<article class="rejection-entry"><div class="rejection-entry-head"><strong>'+safe(p.institute)+'</strong><span class="small">'+safe(p.date?date(p.date):'')+'</span></div><div class="rejection-scores"><div><span>Flávio Bolsonaro</span><strong class="fv">'+fmt(p.f)+'%</strong></div><div><span>Lula</span><strong class="lv">'+fmt(p.l)+'%</strong></div></div><p class="small">'+safe(p.question||'')+'</p><details><summary>Metodologia e fonte</summary><p class="small">Coleta: '+safe(p.field||'Não informada')+' · Amostra: '+safe(p.n||'Não informada')+' · Margem: '+safe(p.margin==null?'Não informada':'±'+p.margin+' p.p.')+'</p><p class="small">Método: '+safe(p.method||'Não informado')+' · Registro: '+safe(p.registration||'Não informado')+'</p>'+(p.source?'<a class="link" target="_blank" rel="noopener noreferrer" href="'+safe(p.source)+'">Consultar fonte ↗</a>':'')+'</details></article>';
  const summary=entries=>{
    if(!entries.length)return '';
    const latest=[...new Map([...entries].sort((a,b)=>a.date.localeCompare(b.date)).map(p=>[p.institute,p])).values()];
    const multiple=latest.length>1;
    const avg=k=>latest.reduce((sum,p)=>sum+p[k],0)/latest.length;
    const subtitle=multiple?'Média simples das últimas rodadas de '+latest.length+' institutos':'Resultado da última rodada · '+safe(latest[0].institute);
    return '<div class="rejection-summary" aria-label="'+safe(subtitle)+'"><div class="eyebrow">'+(multiple?'SÍNTESE DO GRUPO':'PESQUISA MAIS RECENTE')+'</div><h3>'+subtitle+'</h3><div class="rejection-scores"><div><span>Flávio Bolsonaro</span><strong class="fv">'+fmt(avg('f'))+'%</strong></div><div><span>Lula</span><strong class="lv">'+fmt(avg('l'))+'%</strong></div></div><p class="small">'+(multiple?'Cada instituto conta uma vez, usando apenas sua rodada mais recente. Média descritiva, sem ponderação por amostra ou precisão; não é uma estimativa estatística nem possui margem de erro própria.':'Há apenas um instituto neste grupo; o valor exibido não é uma média entre institutos.')+'</p></div>';
  };
  const hero=()=>{
    const exclusive=records.filter(p=>p.group==='exclusive').sort((a,b)=>a.date.localeCompare(b.date));
    if(!exclusive.length)return '<section class="hero rejection-hero"><div class="eyebrow">REJEIÇÃO EXCLUSIVA · SEGUNDO TURNO</div><h2>Sem levantamento confirmado</h2><p>O painel será atualizado quando houver dados verificados.</p></section>';
    const latest=[...new Map(exclusive.map(p=>[p.institute,p])).values()];
    const mean=k=>latest.reduce((total,p)=>total+p[k],0)/latest.length;
    const f=mean('f'),l=mean('l'),diff=Math.abs(f-l);
    const subtitle=latest.length===1?'Última pesquisa · '+safe(latest[0].institute)+' · '+date(latest[0].date):'Média simples · '+latest.length+' institutos · última rodada de cada um';
    const bar=(name,value,color)=>'<div class="rejection-hero-bar"><div class="rejection-hero-label"><span>'+name+'</span><strong>'+fmt(value)+'%</strong></div><div class="rejection-hero-track" role="img" aria-label="'+name+': '+fmt(value)+' por cento de rejeição exclusiva"><span class="'+color+'" style="width:'+Math.max(0,Math.min(100,value))+'%"></span></div></div>';
    return '<section class="hero rejection-hero" aria-labelledby="rejection-hero-title"><div class="eyebrow">REJEIÇÃO EXCLUSIVA · SEGUNDO TURNO</div><h2 id="rejection-hero-title">Rejeição dos candidatos</h2><p class="rejection-hero-subtitle">'+subtitle+'</p><div class="rejection-hero-bars">'+bar('Flávio Bolsonaro',f,'violet')+bar('Lula',l,'coral')+'</div><div class="rejection-hero-bottom"><strong>Diferença: '+fmt(diff)+' p.p.</strong><span>'+(diff===0?'Rejeição exclusiva igual nos dois candidatos':(f>l?'Flávio Bolsonaro':'Lula')+' apresenta maior rejeição exclusiva')+'</span></div><p class="rejection-hero-note">Escala independente de 0 a 100% para cada candidato. Rejeições não são votos válidos e não precisam somar 100%. '+(latest.length===1?'Um instituto; não é média entre institutos.':'Média descritiva sem margem de erro própria.')+'</p></section>';
  };
  main.innerHTML=intro('Rejeição','O limite de crescimento de cada candidatura, com perguntas e metodologias contextualizadas.')+hero()+'<section class="card rejection-explainer" aria-labelledby="rejection-explainer-title"><div class="eyebrow">ENTENDA O INDICADOR</div><h2 id="rejection-explainer-title">O que é rejeição eleitoral?</h2><p>A rejeição mede a parcela de eleitores que declara não votar em determinado candidato. No segundo turno, ajuda a compreender a resistência enfrentada por cada candidatura e suas possibilidades de conquistar novos votos.</p><p>Uma rejeição elevada pode dificultar o crescimento eleitoral, mas não determina o resultado. A decisão também depende da mobilização dos eleitores, da abstenção e dos votos brancos e nulos.</p><p class="small"><strong>Rejeição exclusiva:</strong> considera quem rejeita apenas um dos dois candidatos. É diferente da rejeição geral, que pode incluir eleitores que rejeitam ambos. Rejeição não equivale a intenção de voto nem a uma previsão do resultado.</p></section>'+'<section class="card"><div class="card-head"><div><div class="eyebrow">COMPARAÇÃO RESPONSÁVEL</div><h2>Rejeição dos candidatos</h2><p class="small">Somente perguntas comprovadamente referentes ao confronto de segundo turno entre Lula e Flávio Bolsonaro entram no painel. Os levantamentos são separados pela definição do indicador.</p></div></div><p class="notice">As sínteses abaixo são descritivas e usam apenas a rodada mais recente de cada instituto dentro de seu grupo. Não há média geral entre grupos nem margem de erro calculada para essas sínteses.</p></section>'+groups.map(g=>{const entries=records.filter(p=>p.group===g.id).sort((a,b)=>b.date.localeCompare(a.date));return '<section class="card"><div class="card-head"><div><div class="eyebrow">INDICADOR</div><h2>'+g.title+'</h2><p class="small">'+g.description+'</p></div></div>'+(entries.length?summary(entries)+'<div class="rejection-list">'+entries.map(render).join('')+'</div>'+[...new Set(entries.map(p=>p.institute))].map(name=>{const rounds=entries.filter(p=>p.institute===name).sort((a,b)=>a.date.localeCompare(b.date));return rounds.length>1?'<div class="rejection-evolution"><h3>Evolução · '+safe(name)+'</h3>'+timeChart(rounds)+'</div>':'';}).join(''):'<p class="notice">Nenhum levantamento deste grupo foi confirmado como referente exclusivamente ao segundo turno. Resultados de rejeição geral ficam de fora.</p>')+'</section>';}).join('')+'<p class="small">Rejeição não equivale à intenção de voto. Mesmo dentro de um grupo, mudanças na pergunta, universo ou coleta podem impedir comparações diretas.</p>';
}
let current='';function route(){const h=location.hash.slice(1)||'media';if(['criterios','calculo','limites','historico'].includes(h)){if(current!=='metodologia'){methodology();current='metodologia';}requestAnimationFrame(()=>document.getElementById(h)?.scrollIntoView({behavior:'smooth'}));return;}current=['media','pesquisas','metodologia','tendencia','rejeicao'].includes(h)?h:'media';({media:average,pesquisas:research,metodologia:methodology,tendencia:experimentalTrend,rejeicao:rejection})[current]();document.querySelectorAll('nav a').forEach(a=>{if(a.hash==='#'+current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=({media:'Média',pesquisas:'Pesquisas',metodologia:'Metodologia',tendencia:'Tendência experimental',rejeicao:'Rejeição'})[current]+' • Pulsa';bindTrend();window.scrollTo(0,0);}window.addEventListener('hashchange',route);
function trendSeries(name){return dataset.instituteHistory[name] || polls.filter(p=>p.name===name).map(p=>({date:p.date,f:p.f,l:p.l})).sort((a,b)=>a.date.localeCompare(b.date));}
function trendSection(){return `<section class="card trend-card" id="rodadas-institutos"><div class="card-head"><div><div class="eyebrow">RODADAS DO MESMO INSTITUTO</div><h2>Tendência das intenções de voto</h2><p class="sub">Compare a evolução dentro de uma mesma pesquisa.</p></div><label class="field trend-select">Instituto<select id="trend-institute">${polls.map(p=>`<option ${p.name==='PoderData/Aya'?'selected':''}>${p.name}</option>`).join('')}</select></label></div><div id="trend-content">${renderTrend('PoderData/Aya')}</div></section>`;}
function renderTrend(name){const points=trendSeries(name),last=points.at(-1),first=points[0];if(!last)return '<p>Sem dados disponíveis.</p>';const changes=points.length>1?`<span class="small">Desde ${date(first.date)}: Flávio ${fmt(last.f-first.f)} p.p. · Lula ${last.l-first.l>0?'+':''}${fmt(last.l-first.l)} p.p.</span>`:'';return `<div class="trend-summary"><div><span><i class="dot"></i>Flávio Bolsonaro</span><strong class="fv">${fmt(last.f)}%</strong></div><div><span><i class="dot r"></i>Lula</span><strong class="lv">${fmt(last.l)}%</strong></div><div class="trend-change">${changes}</div></div>${points.length>1?timeChart(points):'<p class="notice">Apenas uma rodada disponível neste instituto. A linha de tendência aparecerá quando uma segunda rodada for incluída.</p>'}<p class="small">${name} · Votos válidos · Datas de divulgação. ${points.length>1?'A diferença entre os candidatos passou de '+fmt(first.f-first.l)+' para '+fmt(last.f-last.l)+' p.p. A variação observada não comprova, sozinha, uma mudança estatisticamente significativa.':'Não há projeção a partir de uma única observação.'}</p><details><summary>Ver dados e fonte</summary><div class="table-wrap"><table><tr><th>Divulgação</th><th>Flávio</th><th>Lula</th></tr>${points.map(p=>`<tr><td>${date(p.date)}</td><td>${fmt(p.f)}%</td><td>${fmt(p.l)}%</td></tr>`).join('')}</table></div><p><a class="link" href="${polls.find(p=>p.name===name).url}" target="_blank" rel="noopener noreferrer">Consultar publicação ↗</a></p></details>`;}
function timeChart(points){const minT=Date.parse(points[0].date),maxT=Date.parse(points.at(-1).date);const low=Math.min(44,...points.flatMap(p=>[p.f,p.l])),high=Math.max(56,...points.flatMap(p=>[p.f,p.l]));const x=p=>70+(Date.parse(p.date)-minT)/(maxT-minT||1)*790,y=v=>30+(high-v)/(high-low)*270;let out=`<svg class="trend-svg" viewBox="0 0 980 355" role="img" aria-label="Evolução entre rodadas: ${points.map(p=>date(p.date)+', Flávio '+fmt(p.f)+'%, Lula '+fmt(p.l)+'%').join('; ')}">`;for(let i=0;i<=4;i++){const v=high-(high-low)*i/4;out+=`<path d="M70 ${y(v)}H860" stroke="#e3e0e5" stroke-dasharray="3 6"/><text x="15" y="${y(v)+5}">${fmt(v)}%</text>`;}out+=`<path d="M70 ${y(50)}H860" stroke="#9e97a3" stroke-dasharray="5 5"/>`;['f','l'].forEach((k,i)=>{const c=i?'#f44330':'#7774df';out+=`<polyline points="${points.map(p=>x(p)+','+y(p[k])).join(' ')}" stroke="${c}" fill="none" stroke-width="3" ${i?'stroke-dasharray="8 4"':''}/>`;points.forEach(p=>{out+=`<circle cx="${x(p)}" cy="${y(p[k])}" r="6" fill="${c}" stroke="white" stroke-width="2"><title>${date(p.date)}: ${fmt(p[k])}%</title></circle>`;});const last=points.at(-1);out+=`<text x="880" y="${y(last[k])+5}" style="fill:${i?'#b8291b':'#514bb0'};font-weight:700">${fmt(last[k])}%</text>`;});points.forEach(p=>out+=`<text x="${x(p)}" y="335" text-anchor="middle">${date(p.date)}</text>`);return out+'</svg>';}
function bindTrend(){const select=document.getElementById('trend-institute');if(select)select.addEventListener('change',()=>{document.getElementById('trend-content').innerHTML=renderTrend(select.value);});}
let checking=false;
async function refreshData(){if(checking)return;checking=true;const status=document.getElementById('sync-status');try{const response=await fetch('data.json?t='+Date.now(),{cache:'no-store'});if(!response.ok)throw Error('HTTP '+response.status);const incoming=await response.json();if(!Array.isArray(incoming.polls)||!Array.isArray(incoming.history))throw Error('Formato inválido');const changed=dataset&&incoming.revision!==dataset.revision;dataset=incoming;polls=incoming.polls;if(!current){route();}else if(changed){const scroll=window.scrollY;if(current==='media'){average();bindTrend();}else if(current==='pesquisas'){research();}else if(current==='tendencia'){experimentalTrend();}else if(current==='rejeicao'){rejection();}else if(current==='metodologia'){methodology();}window.scrollTo(0,scroll);}if(status)status.textContent='Verificado às '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})+' · Nova versão a cada boletim publicado';}catch(error){if(status)status.textContent='Não foi possível sincronizar. Tentaremos novamente em 30 s.';if(!dataset)main.innerHTML='<p class="notice">Não foi possível carregar os dados. Use “Verificar atualização” para tentar novamente.</p>';}finally{checking=false;}}
function startData(){document.querySelector('.campaign-banner').insertAdjacentHTML('afterend','<div class="sync-bar"><span id="sync-status" role="status">Carregando dados…</span><button id="sync-now" type="button">Verificar atualização ↻</button></div>');document.getElementById('sync-now').addEventListener('click',refreshData);refreshData();setInterval(()=>{if(!document.hidden)refreshData();},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshData();});}

startData();
